function serializeQuery(pairs) {
  if (!Array.isArray(pairs)) {
    throw new TypeError("pairs must be an array");
  }

  const encoded = [];
  const hasOwn = Object.prototype.hasOwnProperty;

  for (let i = 0; i < pairs.length; i++) {
    if (!hasOwn.call(pairs, i)) {
      throw new TypeError("pairs must be dense");
    }

    const pair = pairs[i];

    if (
      !Array.isArray(pair) ||
      pair.length !== 2 ||
      !hasOwn.call(pair, 0) ||
      !hasOwn.call(pair, 1) ||
      typeof pair[0] !== "string" ||
      typeof pair[1] !== "string"
    ) {
      throw new TypeError("each pair must be [name, value]");
    }

    encoded.push([rfc3986Encode(pair[0]), rfc3986Encode(pair[1])]);
  }

  encoded.sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    if (a[1] < b[1]) return -1;
    if (a[1] > b[1]) return 1;
    return 0;
  });

  return encoded.map(([name, value]) => `${name}=${value}`).join("&");
}

function rfc3986Encode(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, character =>
    `%${character.charCodeAt(0).toString(16).toUpperCase()}`
  );
}
